import unittest
from unittest.mock import patch
from candidate import will_it_fly

class TestWillItFly(unittest.TestCase):
    def test_normal_palindromic_list_below_weight(self):
        self.assertTrue(will_it_fly([3, 2, 3], 9))

    def test_normal_palindromic_list_exactly_at_weight(self):
        self.assertTrue(will_it_fly([1, 1, 1], 3))

    def test_normal_palindromic_list_above_weight(self):
        self.assertFalse(will_it_fly([3, 2, 3], 1))

    def test_single_element_list(self):
        self.assertTrue(will_it_fly([5], 5))
        self.assertTrue(will_it_fly([5], 10))
        self.assertFalse(will_it_fly([5], 0))

    def test_empty_list(self):
        with self.assertRaises(TypeError):
            will_it_fly([], 5)

    def test_non_palindromic_list_below_weight(self):
        self.assertFalse(will_it_fly([1, 2], 5))

    def test_non_palindromic_list_above_weight(self):
        self.assertFalse(will_it_fly([1, 2, 3], 10))

    def test_palindromic_list_with_negative_numbers(self):
        self.assertTrue(will_it_fly([-1, 2, -1], 0))
        self.assertFalse(will_it_fly([-1, 2, -1], -1))

    def test_palindromic_list_with_floats(self):
        self.assertTrue(will_it_fly([1.5, 2.5, 1.5], 6.5))
        self.assertFalse(will_it_fly([1.5, 2.5, 1.5], 4.0))

    def test_non_palindromic_list_with_floats(self):
        self.assertFalse(will_it_fly([1.5, 2.5], 5.0))

    def test_type_error_with_string(self):
        with self.assertRaises(TypeError):
            will_it_fly("abc", 5)

    def test_type_error_with_none(self):
        with self.assertRaises(TypeError):
            will_it_fly(None, 5)

    def test_list_with_non_integer_elements(self):
        with self.assertRaises(TypeError):
            will_it_fly([1, 'a', 1], 5)

    def test_boundary_condition_equal_weight(self):
        self.assertTrue(will_it_fly([1, 1, 1, 1], 4))

    def test_boundary_condition_exactly_one_element(self):
        self.assertTrue(will_it_fly([1], 1))
        self.assertFalse(will_it_fly([1], 0))

    def test_unbalanced_list_with_zero_weight(self):
        self.assertFalse(will_it_fly([1, 2], 0))

    def test_palindromic_list_with_duplicate_elements(self):
        self.assertTrue(will_it_fly([2, 2, 2, 2], 8))
        self.assertFalse(will_it_fly([2, 2, 2, 2], 7))

if __name__ == '__main__':
    unittest.main()
